#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {}
    virtual void speak() const {
        cout << name << "：" << endl;
    }
};

class OrangeCat : public Cat {
public:
    OrangeCat(string n) : Cat(n) {}
    void speak() const override {
        cout << name << "：我们是学生甲，！" << endl;
    }
};

class TabbyCat : public Cat {
public:
    TabbyCat(string n) : Cat(n) {}
    void speak() const override {
        cout << name << "：我们是学生乙，呜" << endl;
    }
};

int main() {
    OrangeCat o("张三");
    TabbyCat t("李四");
    Cat* cats[2] = { &o, &t };
    for (int i = 0; i < 2; i++) {
        cats[i]->speak();
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {
        cout << "搭对象基类那一半：" << name << endl;
    }
    ~Cat() {
        cout << "拆对象基类那一半：" << name << endl;
    }
};

class Kitten : public Cat {
public:
    Kitten(string n) : Cat(n) {
        cout << "搭子对象那一半：" << name << endl;
    }
    ~Kitten() {
        cout << "拆子对象那一半：" << name << endl;
    }
};

int main() {
    Cat* p = new Kitten("张三");
    delete p;
    return 0;
}
